import{_ as o,Y as a,o as r,c as l,aq as i,H as n}from"./chunks/framework.DpyB0eAw.js";import"./chunks/theme.B8bSfJOi.js";const b=JSON.parse('{"title":"展望未来","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/about/future.md","filePath":"zh-cn/about/future.md"}'),p={name:"zh-cn/about/future.md"};function u(s,e,c,d,m,h){const t=a("NolebaseGitChangelog");return r(),l("div",null,[e[0]||(e[0]=i('<h1 id="looking-toward-the-future" tabindex="-1">展望未来 <a class="header-anchor" href="#looking-toward-the-future" aria-label="Permalink to &quot;展望未来&quot;">​</a></h1><blockquote><p>未来是美好的，也是不确定的，让我们共同期待 <code>BetterAndroid</code> 在未来的发展空间。</p></blockquote><h2 id="future-plans" tabindex="-1">未来的计划 <a class="header-anchor" href="#future-plans" aria-label="Permalink to &quot;未来的计划&quot;">​</a></h2><blockquote><p>这里收录了 <code>BetterAndroid</code> 可能会在后期添加的功能。</p></blockquote><h3 id="project-template-visualization-creation-tool" tabindex="-1">项目模版的可视化创建工具 <a class="header-anchor" href="#project-template-visualization-creation-tool" aria-label="Permalink to &quot;项目模版的可视化创建工具&quot;">​</a></h3><p>介于 Android Studio 提供的模版创建的项目过于冗余，我们在后期可能会推出一个集成了 BetterAndroid 相关依赖的项目模版创建工具，它可能会作为 IntelliJ IDEA 的插件形式存在。</p><p>这个功能将会支持原生 Android 项目和 Jetpack Compose Multiplatform 项目的创建。</p><h3 id="improve-compose-multiplatform" tabindex="-1">完善 compose-multiplatform <a class="header-anchor" href="#improve-compose-multiplatform" aria-label="Permalink to &quot;完善 compose-multiplatform&quot;">​</a></h3><p>目前 <a href="./../library/compose-multiplatform.html">compose-multiplatform</a> 尚在开发测试阶段，目前的计划是继续进行这个模块的开发工作。</p><p>我们欢迎更多的开发者参与到开发中来，如果可能，欢迎提交 PR 为此项目贡献或通过 <a href="https://github.com/BetterAndroid/BetterAndroid/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 向我们提出建议。</p>',10)),n(t)])}const k=o(p,[["render",u]]);export{b as __pageData,k as default};
